    42→public abstract class BeaconStateAccessors {
    43→  protected final SpecConfig config;
    44→  protected final Predicates predicates;
    45→  protected final MiscHelpers miscHelpers;
    46→
    47→  protected BeaconStateAccessors(
    48→      final SpecConfig config, final Predicates predicates, final MiscHelpers miscHelpers) {
    49→    this.config = config;
    50→    this.predicates = predicates;
    51→    this.miscHelpers = miscHelpers;
    52→  }
    53→
    54→  public UInt64 getCurrentEpoch(final BeaconState state) {
    55→    return miscHelpers.computeEpochAtSlot(state.getSlot());
    56→  }
    57→
    58→  public UInt64 getPreviousEpoch(final BeaconState state) {
    59→    UInt64 currentEpoch = getCurrentEpoch(state);
    60→    return currentEpoch.equals(GENESIS_EPOCH) ? GENESIS_EPOCH : currentEpoch.minus(UInt64.ONE);
    61→  }
    62→
    63→  public UInt64 getValidatorChurnLimit(final BeaconState state) {
    64→    final int activeValidatorCount =
    65→        getActiveValidatorIndices(state, getCurrentEpoch(state)).size();
    66→    return getValidatorChurnLimit(activeValidatorCount);
    67→  }
    68→
    69→  public UInt64 getValidatorChurnLimit(final int activeValidatorCount) {
    70→    return UInt64.valueOf(config.getMinPerEpochChurnLimit())
    71→        .max(UInt64.valueOf(activeValidatorCount / config.getChurnLimitQuotient()));
    72→  }
    73→
    74→  public UInt64 getValidatorActivationChurnLimit(final BeaconState state) {
    75→    return getValidatorChurnLimit(state);
    76→  }
    77→
    78→  public Optional<BLSPublicKey> getValidatorPubKey(
    79→      final BeaconState state, final UInt64 validatorIndex) {
    80→    if (validatorIndex.isGreaterThanOrEqualTo(state.getValidators().size())
    81→        || validatorIndex.longValue() < 0) {
    82→      return Optional.empty();
    83→    }
    84→    return Optional.of(
    85→        BeaconStateCache.getTransitionCaches(state)
    86→            .getValidatorsPubKeys()
    87→            .get(
    88→                validatorIndex,
    89→                i -> {
    90→                  BLSPublicKey pubKey = state.getValidators().get(i.intValue()).getPublicKey();
    91→
    92→                  // eagerly pre-cache pubKey => validatorIndex mapping
    93→                  BeaconStateCache.getTransitionCaches(state)
    94→                      .getValidatorIndexCache()
    95→                      .invalidateWithNewValue(pubKey, i.intValue());
    96→                  return pubKey;
    97→                }));
    98→  }
