    78→  public Optional<BLSPublicKey> getValidatorPubKey(
    79→      final BeaconState state, final UInt64 validatorIndex) {
    80→    if (validatorIndex.isGreaterThanOrEqualTo(state.getValidators().size())
    81→        || validatorIndex.longValue() < 0) {
    82→      return Optional.empty();
    83→    }
    84→    return Optional.of(
    85→        BeaconStateCache.getTransitionCaches(state)
    86→            .getValidatorsPubKeys()
    87→            .get(
    88→                validatorIndex,
    89→                i -> {
    90→                  BLSPublicKey pubKey = state.getValidators().get(i.intValue()).getPublicKey();
    91→
    92→                  // eagerly pre-cache pubKey => validatorIndex mapping
    93→                  BeaconStateCache.getTransitionCaches(state)
    94→                      .getValidatorIndexCache()
    95→                      .invalidateWithNewValue(pubKey, i.intValue());
    96→                  return pubKey;
    97→                }));
