   100→  /**
   101→   * Get active validator indices at ``epoch``.
   102→   *
   103→   * @param state - Current BeaconState
   104→   * @param epoch - The epoch under consideration.
   105→   * @return A list of indices representing the active validators for the given epoch.
   106→   */
   107→  public IntList getActiveValidatorIndices(final BeaconState state, final UInt64 epoch) {
   108→    final UInt64 stateEpoch = getCurrentEpoch(state);
   109→    final UInt64 maxLookaheadEpoch = getMaxLookaheadEpoch(stateEpoch);
   110→    checkArgument(
   111→        epoch.isLessThanOrEqualTo(maxLookaheadEpoch),
   112→        "Cannot get active validator indices from an epoch beyond the seed lookahead period. Requested epoch %s from state in epoch %s",
   113→        epoch,
   114→        stateEpoch);
   115→    return BeaconStateCache.getTransitionCaches(state)
   116→        .getActiveValidators()
   117→        .get(
   118→            epoch,
   119→            e -> {
   120→              SszList<Validator> validators = state.getValidators();
   121→              return IntList.of(
   122→                  IntStream.range(0, validators.size())
   123→                      .filter(index -> predicates.isActiveValidator(validators.get(index), epoch))
   124→                      .toArray());
   125→            });
   126→  }
