   128→  public UInt64 getMaxLookaheadEpoch(final BeaconState state) {
   129→    return getMaxLookaheadEpoch(getCurrentEpoch(state));
   130→  }
   131→
   132→  private UInt64 getMaxLookaheadEpoch(final UInt64 stateEpoch) {
   133→    return stateEpoch.plus(config.getMaxSeedLookahead());
   134→  }
