   136→  public UInt64 getTotalBalance(final BeaconState state, final Collection<Integer> indices) {
   137→    UInt64 sum = UInt64.ZERO;
   138→    SszList<Validator> validatorRegistry = state.getValidators();
   139→    for (Integer index : indices) {
   140→      sum = sum.plus(validatorRegistry.get(index).getEffectiveBalance());
   141→    }
   142→    return sum.max(config.getEffectiveBalanceIncrement());
   143→  }
   144→
   145→  public UInt64 getTotalActiveBalance(final BeaconState state) {
   146→    return BeaconStateCache.getTransitionCaches(state)
   147→        .getTotalActiveBalance()
   148→        .get(
   149→            getCurrentEpoch(state),
   150→            epoch -> getTotalBalance(state, getActiveValidatorIndices(state, epoch)));
   151→  }
