   153→  public UInt64 getProposerBoostAmount(final BeaconState state) {
   154→    final UInt64 committeeWeight =
   155→        getTotalActiveBalance(state).dividedBy(config.getSlotsPerEpoch());
   156→    return committeeWeight.times(config.getProposerScoreBoost()).dividedBy(100);
