   159→  public Bytes32 getSeed(final BeaconState state, final UInt64 epoch, final Bytes4 domainType)
   160→      throws IllegalArgumentException {
   161→    final UInt64 randaoIndex =
   162→        epoch.plus(config.getEpochsPerHistoricalVector() - config.getMinSeedLookahead() - 1);
   163→    final Bytes32 mix = getRandaoMix(state, randaoIndex);
   164→    final Bytes epochBytes = uint64ToBytes(epoch);
   165→    return Hash.sha256(domainType.getWrappedBytes(), epochBytes, mix);
   166→  }
