   291→  public IntList getBeaconCommittee(
   292→      final BeaconState state, final UInt64 slot, final UInt64 index) {
   293→    // Make sure state is within range of the slot being queried
   294→    validateStateForCommitteeQuery(state, slot);
   295→
   296→    return BeaconStateCache.getTransitionCaches(state)
   297→        .getBeaconCommittee()
   298→        .get(
   299→            TekuPair.of(slot, index),
   300→            __ -> {
   301→              UInt64 epoch = miscHelpers.computeEpochAtSlot(slot);
   302→              UInt64 committeesPerSlot = getCommitteeCountPerSlot(state, epoch);
   303→              int committeeIndex =
   304→                  slot.mod(config.getSlotsPerEpoch())
   305→                      .times(committeesPerSlot)
   306→                      .plus(index)
   307→                      .intValue();
   308→              int count = committeesPerSlot.times(config.getSlotsPerEpoch()).intValue();
   309→              return miscHelpers.computeCommittee(
   310→                  state,
   311→                  getActiveValidatorIndices(state, epoch),
   312→                  getSeed(state, epoch, Domain.BEACON_ATTESTER),
   313→                  committeeIndex,
   314→                  count);
   315→            });
   316→  }
