   320→        .getBeaconCommitteesSize()
   321→        .get(
   322→            slot,
   323→            __ -> {
   324→              final UInt64 epoch = miscHelpers.computeEpochAtSlot(slot);
   325→              final UInt64 committees = getCommitteeCountPerSlot(state, epoch);
   326→              final Int2IntMap committeesSize = new Int2IntOpenHashMap(committees.intValue());
   327→              UInt64.range(UInt64.ZERO, committees)
   328→                  .forEach(
   329→                      index -> {
   330→                        final IntList committee = getBeaconCommittee(state, slot, index);
   331→                        committeesSize.put(index.intValue(), committee.size());
   332→                      });
   333→              return committeesSize;
   334→            });
   335→  }
