    59→  public static BlobSidecarGossipValidator create(
    60→      final Spec spec,
    61→      final Map<Bytes32, BlockImportResult> invalidBlockRoots,
    62→      final GossipValidationHelper validationHelper,
    63→      final MiscHelpersDeneb miscHelpersDeneb,
    64→      final KZG kzg) {
    65→
    66→    final Optional<Integer> maybeMaxBlobsPerBlock = spec.getMaxBlobsPerBlockForHighestMilestone();
    67→
    68→    final int validInfoSize = VALID_BLOCK_SET_SIZE * maybeMaxBlobsPerBlock.orElse(1);
    69→    // It's not fatal if we miss something and we don't need finalized data
    70→    final int validSignedBlockHeadersSize =
    71→        spec.getGenesisSpec().getSlotsPerEpoch() * BEST_CASE_NON_FINALIZED_EPOCHS;
    72→
    73→    return new BlobSidecarGossipValidator(
    74→        spec,
    75→        invalidBlockRoots,
    76→        validationHelper,
    77→        miscHelpersDeneb,
    78→        kzg,
    79→        LimitedSet.createSynchronized(validInfoSize),
    80→        LimitedSet.createSynchronized(validSignedBlockHeadersSize));
    81→  }
    82→
    83→  @VisibleForTesting
    84→  Set<SlotProposerIndexAndBlobIndex> getReceivedValidBlobSidecarInfoSet() {
    85→    return receivedValidBlobSidecarInfoSet;
    86→  }
    87→
    88→  private BlobSidecarGossipValidator(
    89→      final Spec spec,
    90→      final Map<Bytes32, BlockImportResult> invalidBlockRoots,
    91→      final GossipValidationHelper gossipValidationHelper,
    92→      final MiscHelpersDeneb miscHelpersDeneb,
    93→      final KZG kzg,
    94→      final Set<SlotProposerIndexAndBlobIndex> receivedValidBlobSidecarInfoSet,
    95→      final Set<Bytes32> validSignedBlockHeaders) {
    96→    this.spec = spec;
    97→    this.invalidBlockRoots = invalidBlockRoots;
    98→    this.gossipValidationHelper = gossipValidationHelper;
    99→    this.miscHelpersDeneb = miscHelpersDeneb;
   100→    this.kzg = kzg;
   101→    this.receivedValidBlobSidecarInfoSet = receivedValidBlobSidecarInfoSet;
   102→    this.validSignedBlockHeaders = validSignedBlockHeaders;
   103→  }
   104→
   105→  public SafeFuture<InternalValidationResult> validate(final BlobSidecar blobSidecar) {
   106→
   107→    final BeaconBlockHeader blockHeader = blobSidecar.getSignedBeaconBlockHeader().getMessage();
   108→
   109→    /*
   110→     * [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index, blob_sidecar.index)
   111→     *  with valid header signature, sidecar inclusion proof, and kzg proof.
   112→     */
   113→    if (!isFirstValidForSlotProposerIndexAndBlobIndex(blobSidecar, blockHeader)) {
   114→      LOG.trace("BlobSidecar is not the first valid for its slot and index. It will be dropped");
   115→      return completedFuture(InternalValidationResult.IGNORE);
   116→    }
   117→
   118→    /*
   119→     * [REJECT] The sidecar's index is consistent with `MAX_BLOBS_PER_BLOCK` -- i.e. `blob_sidecar.index < MAX_BLOBS_PER_BLOCK`.
   120→     */
   121→    final Optional<Integer> maxBlobsPerBlockAtSlot =
   122→        spec.getMaxBlobsPerBlockAtSlot(blobSidecar.getSlot());
   123→
   124→    if (maxBlobsPerBlockAtSlot.isEmpty()) {
   125→      return completedFuture(reject("BlobSidecar's slot is pre-Deneb"));
   126→    }
   127→    if (blobSidecar.getIndex().isGreaterThanOrEqualTo(maxBlobsPerBlockAtSlot.get())) {
   128→      return completedFuture(reject("BlobSidecar index is greater than MAX_BLOBS_PER_BLOCK"));
   129→    }
   130→
   131→    /*
   132→     * [REJECT] The sidecar is for the correct subnet -- i.e. `compute_subnet_for_blob_sidecar(blob_sidecar.index) == subnet_id`.
   133→     *
   134→     * This rule is already implemented in
   135→     * tech.pegasys.teku.networking.eth2.gossip.BlobSidecarGossipManager.TopicSubnetIdAwareOperationProcessor
   136→     */
   137→
   138→    /*
   139→     * [IGNORE]_ The sidecar is not from a future slot (with a `MAXIMUM_GOSSIP_CLOCK_DISPARITY` allowance) -- i.e. validate
   140→     * that `block_header.slot <= current_slot` (a client MAY queue future sidecars for processing at the appropriate slot).
   141→     */
   142→    if (gossipValidationHelper.isSlotFromFuture(blockHeader.getSlot())) {
   143→      LOG.trace("BlobSidecar is from the future. It will be saved for future processing");
   144→      return completedFuture(InternalValidationResult.SAVE_FOR_FUTURE);
   145→    }
   146→
   147→    /*
   148→     * [IGNORE] The sidecar is from a slot greater than the latest finalized slot -- i.e. validate that
   149→     * `block_header.slot > compute_start_slot_at_epoch(store.finalized_checkpoint.epoch)`
   150→     */
   151→    if (gossipValidationHelper.isSlotFinalized(blockHeader.getSlot())) {
   152→      LOG.trace("BlobSidecar is too old (slot already finalized)");
   153→      return completedFuture(InternalValidationResult.IGNORE);
   154→    }
   155→
   156→    // Optimization: If we have already completely verified BlobSidecar with the same
   157→    // SignedBlockHeader, we can skip most steps and jump to shortened validation
   158→    if (validSignedBlockHeaders.contains(blobSidecar.getSignedBeaconBlockHeader().hashTreeRoot())) {
   159→      return validateBlobSidecarWithKnownValidHeader(blobSidecar, blockHeader);
   160→    }
   161→
   162→    /*
   163→     * [REJECT] The proposer signature of `blob_sidecar.signed_block_header`, is valid with respect
   164→     * to the `block_header.proposer_index` pubkey.
   165→     *
   166→     * Verified later after all checks not involving state are passed
   167→     */
   168→
   169→    /*
   170→     * [IGNORE] The sidecar's block's parent (defined by `block_header.parent_root`) has been seen (via both gossip and
   171→     * non-gossip sources) (a client MAY queue sidecars for processing once the parent block is retrieved).
   172→     */
   173→    if (!gossipValidationHelper.isBlockAvailable(blockHeader.getParentRoot())) {
   174→      LOG.trace(
   175→          "BlobSidecar parent block is not available. It will be saved for future processing");
   176→      return completedFuture(InternalValidationResult.SAVE_FOR_FUTURE);
   177→    }
   178→    final Optional<UInt64> maybeParentBlockSlot =
   179→        gossipValidationHelper.getSlotForBlockRoot(blockHeader.getParentRoot());
   180→    if (maybeParentBlockSlot.isEmpty()) {
   181→      LOG.trace("BlobSidecar parent block does not exist. It will be saved for future processing");
   182→      return completedFuture(InternalValidationResult.SAVE_FOR_FUTURE);
   183→    }
   184→    final UInt64 parentBlockSlot = maybeParentBlockSlot.get();
   185→
   186→    /*
   187→     * [REJECT] The sidecar's block's parent (defined by `block_header.parent_root`) passes validation.
   188→     */
   189→    if (invalidBlockRoots.containsKey(blockHeader.getParentRoot())) {
   190→      return completedFuture(reject("BlobSidecar block header has an invalid parent root"));
   191→    }
   192→
   193→    /*
   194→     * [REJECT] The sidecar is from a higher slot than the sidecar's block's parent (defined by `block_header.parent_root`).
   195→     */
   196→    if (!blockHeader.getSlot().isGreaterThan(parentBlockSlot)) {
   197→      return completedFuture(reject("Parent block is after BlobSidecar slot."));
   198→    }
   199→
   200→    /*
   201→     * [REJECT] The current finalized_checkpoint is an ancestor of the sidecar's block -- i.e.
   202→     * `get_checkpoint_block(store, block_header.parent_root, store.finalized_checkpoint.epoch) == store.finalized_checkpoint.root`.
   203→     */
   204→    if (!gossipValidationHelper.currentFinalizedCheckpointIsAncestorOfBlock(
   205→        blockHeader.getSlot(), blockHeader.getParentRoot())) {
   206→      return completedFuture(
   207→          reject("BlobSidecar block header does not descend from finalized checkpoint"));
   208→    }
   209→
   210→    /*
   211→     * [REJECT] The sidecar's inclusion proof is valid as verified by `verify_blob_sidecar_inclusion_proof(blob_sidecar)`.
   212→     */
   213→    if (!miscHelpersDeneb.verifyBlobKzgCommitmentInclusionProof(blobSidecar)) {
   214→      return completedFuture(reject("BlobSidecar inclusion proof validation failed"));
   215→    }
   216→
   217→    /*
   218→     * [REJECT] The sidecar's blob is valid as verified by
   219→     * `verify_blob_kzg_proof(blob_sidecar.blob, blob_sidecar.kzg_commitment, blob_sidecar.kzg_proof)`.
   220→     */
   221→    if (!miscHelpersDeneb.verifyBlobKzgProof(kzg, blobSidecar)) {
   222→      return completedFuture(reject("BlobSidecar does not pass kzg validation"));
   223→    }
   224→
   225→    return gossipValidationHelper
   226→        .getParentStateInBlockEpoch(
   227→            parentBlockSlot, blockHeader.getParentRoot(), blockHeader.getSlot())
   228→        .thenApply(
   229→            maybePostState -> {
   230→              /*
   231→               * [REJECT] The sidecar is proposed by the expected `proposer_index` for the block's slot in the context of the current
   232→               *  shuffling (defined by `block_header.parent_root`/`block_header.slot`).
   233→               *
   234→               * If the `proposer_index` cannot immediately be verified against the expected shuffling, the sidecar MAY be queued for
   235→               * later processing while proposers for the block's branch are calculated -- in such a case
   236→               * _do not_ `REJECT`, instead `IGNORE` this message.
   237→               */
   238→              if (maybePostState.isEmpty()) {
   239→                LOG.trace(
   240→                    "BlobSidecar block header state wasn't available. Must have been pruned by finalized.");
   241→                return InternalValidationResult.IGNORE;
   242→              }
   243→              final BeaconState postState = maybePostState.get();
   244→              if (!gossipValidationHelper.isProposerTheExpectedProposer(
   245→                  blockHeader.getProposerIndex(), blockHeader.getSlot(), postState)) {
   246→                return reject(
   247→                    "BlobSidecar block header proposed by incorrect proposer (%s).",
   248→                    blockHeader.getProposerIndex());
   249→              }
   250→
   251→              /*
   252→               * [REJECT] The proposer signature of `blob_sidecar.signed_block_header`, is valid
   253→               * with respect to the `block_header.proposer_index` pubkey.
   254→               */
   255→              if (!verifyBlockHeaderSignature(postState, blobSidecar)) {
   256→                return reject("BlobSidecar block header signature is invalid.");
   257→              }
   258→
   259→              /*
   260→               * Checking it again at the very end because whole method is not synchronized
   261→               *
   262→               * [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index, blob_sidecar.index)
   263→               *  with valid header signature, sidecar inclusion proof, and kzg proof.
   264→               */
   265→              if (!markForEquivocation(blockHeader, blobSidecar.getIndex())) {
   266→                return ignore(
   267→                    "BlobSidecar is not the first valid for its slot and index. It will be dropped.");
   268→              }
   269→
   270→              validSignedBlockHeaders.add(blobSidecar.getSignedBeaconBlockHeader().hashTreeRoot());
   271→
   272→              return ACCEPT;
   273→            });
   274→  }
   275→
   276→  private boolean markForEquivocation(final BeaconBlockHeader blockHeader, final UInt64 index) {
   277→    return receivedValidBlobSidecarInfoSet.add(
   278→        new SlotProposerIndexAndBlobIndex(
   279→            blockHeader.getSlot(), blockHeader.getProposerIndex(), index));
   280→  }
   281→
   282→  public boolean markForEquivocation(final BlobSidecar blobSidecar) {
   283→    return markForEquivocation(
   284→        blobSidecar.getSignedBeaconBlockHeader().getMessage(), blobSidecar.getIndex());
   285→  }
   286→
   287→  private SafeFuture<InternalValidationResult> validateBlobSidecarWithKnownValidHeader(
   288→      final BlobSidecar blobSidecar, final BeaconBlockHeader blockHeader) {
   289→
   290→    blobSidecar.markSignatureAsValidated();
   291→
   292→    /*
   293→     * [REJECT] The sidecar's inclusion proof is valid as verified by `verify_blob_sidecar_inclusion_proof(blob_sidecar)`.
   294→     */
   295→    if (!miscHelpersDeneb.verifyBlobKzgCommitmentInclusionProof(blobSidecar)) {
   296→      return completedFuture(reject("BlobSidecar inclusion proof validation failed"));
   297→    }
   298→
   299→    /*
   300→     * [REJECT] The sidecar's blob is valid as verified by
   301→     * `verify_blob_kzg_proof(blob_sidecar.blob, blob_sidecar.kzg_commitment, blob_sidecar.kzg_proof)`.
   302→     */
   303→    if (!miscHelpersDeneb.verifyBlobKzgProof(kzg, blobSidecar)) {
   304→      return completedFuture(reject("BlobSidecar does not pass kzg validation"));
   305→    }
   306→
   307→    // This can be changed between two received BlobSidecars from one block, so checking
   308→    /*
   309→     * [REJECT] The current finalized_checkpoint is an ancestor of the sidecar's block -- i.e.
   310→     * `get_checkpoint_block(store, block_header.parent_root, store.finalized_checkpoint.epoch) == store.finalized_checkpoint.root`.
   311→     */
   312→    if (!gossipValidationHelper.currentFinalizedCheckpointIsAncestorOfBlock(
   313→        blockHeader.getSlot(), blockHeader.getParentRoot())) {
   314→      return completedFuture(
   315→          reject("BlobSidecar block header does not descend from finalized checkpoint"));
   316→    }
   317→
   318→    /*
   319→     * [IGNORE] The sidecar is the first sidecar for the tuple (block_header.slot, block_header.proposer_index, blob_sidecar.index)
   320→     *  with valid header signature, sidecar inclusion proof, and kzg proof.
   321→     */
   322→    if (!markForEquivocation(blockHeader, blobSidecar.getIndex())) {
   323→      return SafeFuture.completedFuture(
   324→          ignore("BlobSidecar is not the first valid for its slot and index. It will be dropped."));
   325→    }
   326→
   327→    return SafeFuture.completedFuture(ACCEPT);
   328→  }
   329→
   330→  private boolean verifyBlockHeaderSignature(
   331→      final BeaconState state, final BlobSidecar blobSidecar) {
   332→    final SignedBeaconBlockHeader signedBlockHeader = blobSidecar.getSignedBeaconBlockHeader();
   333→    final Bytes32 domain =
   334→        spec.getDomain(
   335→            Domain.BEACON_PROPOSER,
   336→            spec.getCurrentEpoch(state),
   337→            state.getFork(),
   338→            state.getGenesisValidatorsRoot());
   339→    final Bytes signingRoot = spec.computeSigningRoot(signedBlockHeader.getMessage(), domain);
   340→
   341→    final boolean result =
   342→        gossipValidationHelper.isSignatureValidWithRespectToProposerIndex(
   343→            signingRoot,
   344→            signedBlockHeader.getMessage().getProposerIndex(),
   345→            signedBlockHeader.getSignature(),
   346→            state);
   347→
   348→    if (result) {
   349→      blobSidecar.markSignatureAsValidated();
   350→    }
   351→
   352→    return result;
   353→  }
   354→
   355→  private boolean isFirstValidForSlotProposerIndexAndBlobIndex(
   356→      final BlobSidecar blobSidecar, final BeaconBlockHeader blockHeader) {
   357→    return !receivedValidBlobSidecarInfoSet.contains(
   358→        new SlotProposerIndexAndBlobIndex(
   359→            blockHeader.getSlot(), blockHeader.getProposerIndex(), blobSidecar.getIndex()));
   360→  }
   361→
   362→  record SlotProposerIndexAndBlobIndex(UInt64 slot, UInt64 proposerIndex, UInt64 blobIndex) {}
   363→}
