    58→public abstract class AbstractEpochProcessor implements EpochProcessor {
    59→  protected final SpecConfig specConfig;
    60→  protected final MiscHelpers miscHelpers;
    61→  protected final ValidatorsUtil validatorsUtil;
    62→  protected final BeaconStateUtil beaconStateUtil;
    63→  protected final ValidatorStatusFactory validatorStatusFactory;
    64→  private final SchemaDefinitions schemaDefinitions;
    65→  protected final BeaconStateAccessors beaconStateAccessors;
    66→  protected final BeaconStateMutators beaconStateMutators;
    67→
    68→  private static final Logger LOG = LogManager.getLogger();
    69→  protected final UInt64 maxEffectiveBalance;
    70→  // Used to log once per minute (throttlingPeriod = 60 seconds)
    71→  private final Throttler<Logger> loggerThrottler = new Throttler<>(LOG, UInt64.valueOf(60));
    72→  private final TimeProvider timeProvider;
    73→
    74→  protected AbstractEpochProcessor(
    75→      final SpecConfig specConfig,
    76→      final MiscHelpers miscHelpers,
    77→      final BeaconStateAccessors beaconStateAccessors,
    78→      final BeaconStateMutators beaconStateMutators,
    79→      final ValidatorsUtil validatorsUtil,
    80→      final BeaconStateUtil beaconStateUtil,
    81→      final ValidatorStatusFactory validatorStatusFactory,
    82→      final SchemaDefinitions schemaDefinitions,
    83→      final TimeProvider timeProvider) {
    84→    this.specConfig = specConfig;
    85→    this.miscHelpers = miscHelpers;
    86→    this.beaconStateAccessors = beaconStateAccessors;
    87→    this.beaconStateMutators = beaconStateMutators;
    88→    this.validatorsUtil = validatorsUtil;
    89→    this.beaconStateUtil = beaconStateUtil;
    90→    this.validatorStatusFactory = validatorStatusFactory;
    91→    this.schemaDefinitions = schemaDefinitions;
    92→    this.maxEffectiveBalance = specConfig.getMaxEffectiveBalance();
    93→    this.timeProvider = timeProvider;
    94→  }
    95→
    96→  /**
    97→   * Processes epoch
    98→   *
    99→   * @param preState state prior to epoch transition
   100→   * @throws EpochProcessingException if processing fails
   101→   */
   102→  @Override
   103→  public BeaconState processEpoch(final BeaconState preState) throws EpochProcessingException {
   104→    return preState.updated(mutableState -> processEpoch(preState, mutableState));
   105→  }
   106→
   107→  protected void processEpoch(final BeaconState preState, final MutableBeaconState state)
   108→      throws EpochProcessingException {
   109→    // After Electra, it is possible that the validator set is updated within epoch processing
   110→    // (process_pending_deposits). This is handled by recreateValidatorStatusIfNewValidatorsAreFound
   111→    // (post-Electra)
   112→    ValidatorStatuses validatorStatuses = validatorStatusFactory.createValidatorStatuses(preState);
   113→
   114→    final UInt64 currentEpoch = beaconStateAccessors.getCurrentEpoch(state);
   115→    final TotalBalances totalBalances = validatorStatuses.getTotalBalances();
   116→
   117→    updateTransitionCaches(state, currentEpoch, totalBalances);
   118→
   119→    final TransitionCaches transitionCaches = BeaconStateCache.getTransitionCaches(state);
   120→    final ProgressiveTotalBalancesUpdates progressiveTotalBalances =
   121→        transitionCaches.getProgressiveTotalBalances();
   122→    progressiveTotalBalances.onEpochTransition(validatorStatuses.getStatuses());
   123→    processJustificationAndFinalization(state, totalBalances);
   124→    processInactivityUpdates(state, validatorStatuses);
   125→    processRewardsAndPenalties(state, validatorStatuses);
   126→    processRegistryUpdates(state, validatorStatuses.getStatuses());
   127→    processSlashings(state, validatorStatuses);
   128→    processEth1DataReset(state);
   129→    processPendingDeposits(state);
   130→
   131→    if (shouldCheckNewValidatorsDuringEpochProcessing()) {
   132→      validatorStatuses =
   133→          recreateValidatorStatusIfNewValidatorsAreFound(state, validatorStatuses, currentEpoch);
   134→    }
   135→
   136→    processPendingConsolidations(state);
   137→    processEffectiveBalanceUpdates(state, validatorStatuses.getStatuses());
   138→    processSlashingsReset(state);
   139→    processRandaoMixesReset(state);
   140→    processHistoricalRootsUpdate(state);
   141→    processHistoricalSummariesUpdate(state);
   142→    processParticipationUpdates(state);
   143→    processSyncCommitteeUpdates(state);
   144→    processProposerLookahead(state);
   145→
   146→    if (beaconStateAccessors.isInactivityLeak(state)) {
   147→      loggerThrottler.invoke(
   148→          timeProvider.getTimeInSeconds(), (log) -> log.info("Beacon chain is in inactivity leak"));
   149→    }
   150→  }

