    38→  public EpochProcessorFulu(
    39→      final SpecConfigFulu specConfig,
    40→      final MiscHelpersFulu miscHelpers,
    41→      final BeaconStateAccessorsAltair beaconStateAccessors,
    42→      final BeaconStateMutators beaconStateMutators,
