    62→  /** process_proposer_lookahead */
    63→  @Override
    64→  public void processProposerLookahead(final MutableBeaconState state) {
    65→    final MutableBeaconStateFulu stateFulu = MutableBeaconStateFulu.required(state);
    66→
    67→    // Shift out proposers in the first epoch
    68→    final List<UInt64> proposerIndicesToShiftOut =
    69→        stateFulu
    70→            .getProposerLookahead()
    71→            .asListUnboxed()
    72→            .subList(specConfig.getSlotsPerEpoch(), stateFulu.getProposerLookahead().size());
    73→
    74→    // Fill in the last epoch with new proposer indices
    75→    final List<UInt64> lastEpochProposerIndices =
    76→        stateAccessorsFulu
    77→            .getBeaconProposerIndices(
    78→                stateFulu,
    79→                beaconStateAccessors
    80→                    .getCurrentEpoch(stateFulu)
    81→                    .plus(specConfig.getMinSeedLookahead())
    82→                    .plus(1))
    83→            .stream()
    84→            .map(UInt64::valueOf)
    85→            .toList();
    86→
    87→    final List<UInt64> proposerLookahead = new ArrayList<>(proposerIndicesToShiftOut);
    88→    proposerLookahead.addAll(lastEpochProposerIndices);
    89→
    90→    stateFulu.setProposerLookahead(
    91→        schemaDefinitionsFulu.getProposerLookaheadSchema().of(proposerLookahead));
    92→  }
    93→}
