   106→
   107→  protected void processEpoch(final BeaconState preState, final MutableBeaconState state)
   108→      throws EpochProcessingException {
   109→    // After Electra, it is possible that the validator set is updated within epoch processing
   110→    // (process_pending_deposits). This is handled by recreateValidatorStatusIfNewValidatorsAreFound
   111→    // (post-Electra)
   112→    ValidatorStatuses validatorStatuses = validatorStatusFactory.createValidatorStatuses(preState);
   113→
   114→    final UInt64 currentEpoch = beaconStateAccessors.getCurrentEpoch(state);
   115→    final TotalBalances totalBalances = validatorStatuses.getTotalBalances();
   116→
   117→    updateTransitionCaches(state, currentEpoch, totalBalances);
   118→
   119→    final TransitionCaches transitionCaches = BeaconStateCache.getTransitionCaches(state);
   120→    final ProgressiveTotalBalancesUpdates progressiveTotalBalances =
   121→        transitionCaches.getProgressiveTotalBalances();
   122→    progressiveTotalBalances.onEpochTransition(validatorStatuses.getStatuses());
   123→    processJustificationAndFinalization(state, totalBalances);
   124→    processInactivityUpdates(state, validatorStatuses);
   125→    processRewardsAndPenalties(state, validatorStatuses);
   126→    processRegistryUpdates(state, validatorStatuses.getStatuses());
   127→    processSlashings(state, validatorStatuses);
   128→    processEth1DataReset(state);
   129→    processPendingDeposits(state);
   130→
   131→    if (shouldCheckNewValidatorsDuringEpochProcessing()) {
   132→      validatorStatuses =
   133→          recreateValidatorStatusIfNewValidatorsAreFound(state, validatorStatuses, currentEpoch);
   134→    }
   135→
   136→    processPendingConsolidations(state);
   137→    processEffectiveBalanceUpdates(state, validatorStatuses.getStatuses());
   138→    processSlashingsReset(state);
   139→    processRandaoMixesReset(state);
   140→    processHistoricalRootsUpdate(state);
   141→    processHistoricalSummariesUpdate(state);
   142→    processParticipationUpdates(state);
   143→    processSyncCommitteeUpdates(state);
   144→    processProposerLookahead(state);
   145→
   146→    if (beaconStateAccessors.isInactivityLeak(state)) {
   147→      loggerThrottler.invoke(
   148→          timeProvider.getTimeInSeconds(), (log) -> log.info("Beacon chain is in inactivity leak"));
   149→    }
   150→  }
