   152→  @VisibleForTesting
   153→  public ValidatorStatuses recreateValidatorStatusIfNewValidatorsAreFound(
   154→      final BeaconState state,
   155→      final ValidatorStatuses validatorStatuses,
   156→      final UInt64 currentEpoch) {
   157→    final int cachedValidatorCount = validatorStatuses.getValidatorCount();
   158→    final int stateValidatorCount = state.getValidators().size();
   159→    if (stateValidatorCount > cachedValidatorCount) {
   160→      // New validators added, create new  validator statuses
   161→      final List<ValidatorStatus> newValidatorStatuses =
   162→          new ArrayList<>(stateValidatorCount - cachedValidatorCount);
   163→      for (int i = cachedValidatorCount; i < stateValidatorCount; i++) {
   164→        final ValidatorStatus status =
   165→            validatorStatusFactory.createValidatorStatus(
   166→                state.getValidators().get(i), currentEpoch.minusMinZero(1), currentEpoch);
   167→        newValidatorStatuses.add(status);
   168→      }
   169→      return validatorStatusFactory.recreateValidatorStatuses(
   170→          validatorStatuses, newValidatorStatuses);
   171→    } else {
   172→      return validatorStatuses;
   173→    }
   174→  }
