    71→      final SignedBlockContainer blockContainer,
    72→      final BroadcastValidationLevel broadcastValidationLevel,
    73→      final BlockPublishingPerformance blockPublishingPerformance) {
    74→    return blockFactory
    75→        .unblindSignedBlockIfBlinded(blockContainer.getSignedBlock(), blockPublishingPerformance)
    76→        .thenCompose(
    77→            // creating blob sidecars after unblinding the block to ensure in the blinded flow we
    78→            // will have the cached builder payload
    79→            maybeSignedBlock -> {
    80→              // Fulu, Builder didn't reveal full block
    81→              if (maybeSignedBlock.isEmpty()) {
    82→                return SafeFuture.completedFuture(
    83→                    new BlockImportAndBroadcastValidationResults(
    84→                        SafeFuture.completedFuture(BlockImportResult.BUILDER_WITHHOLD)));
    85→              }
    86→
    87→              final SignedBeaconBlock signedBeaconBlock = maybeSignedBlock.get();
    88→              if (blockContainer.supportsCellProofs()) {
    89→                return gossipAndImportUnblindedSignedBlockAndDataColumnSidecars(
    90→                    signedBeaconBlock,
    91→                    Suppliers.memoize(() -> blockFactory.createDataColumnSidecars(blockContainer)),
    92→                    broadcastValidationLevel,
    93→                    blockPublishingPerformance);
    94→              } else {
    95→                return gossipAndImportUnblindedSignedBlockAndBlobSidecars(
    96→                    signedBeaconBlock,
    97→                    Suppliers.memoize(() -> blockFactory.createBlobSidecars(blockContainer)),
    98→                    broadcastValidationLevel,
    99→                    blockPublishingPerformance);
