    51→
    52→/**
    53→ * <a
    54→ * href="https://github.com/ethereum/consensus-specs/blob/master/specs/fulu/p2p-interface.md#datacolumnsidecarsbyrange-v1">DataColumnSidecarsByRange
    55→ * v1</a>
    56→ */
    57→public class DataColumnSidecarsByRangeMessageHandler
    58→    extends PeerRequiredLocalMessageHandler<
    59→        DataColumnSidecarsByRangeRequestMessage, DataColumnSidecar> {
    60→
    61→  private static final Logger LOG = LogManager.getLogger();
    62→
    63→  private final SpecConfigFulu specConfigFulu;
    64→  private final CombinedChainDataClient combinedChainDataClient;
    65→  private final LabelledMetric<Counter> requestCounter;
    66→  private final Counter totalDataColumnSidecarsRequestedCounter;
    67→  private final DasReqRespLogger dasLogger;
    68→
    69→  public DataColumnSidecarsByRangeMessageHandler(
    70→      final SpecConfigFulu specConfigFulu,
    71→      final MetricsSystem metricsSystem,
    72→      final CombinedChainDataClient combinedChainDataClient,
    73→      final DasReqRespLogger dasLogger) {
    74→    this.specConfigFulu = specConfigFulu;
    75→    this.combinedChainDataClient = combinedChainDataClient;
    76→    requestCounter =
    77→        metricsSystem.createLabelledCounter(
    78→            TekuMetricCategory.NETWORK,
    79→            "rpc_data_column_sidecars_by_range_requests_total",
    80→            "Total number of data column sidecars by range requests received",
    81→            "status");
    82→    totalDataColumnSidecarsRequestedCounter =
    83→        metricsSystem.createCounter(
    84→            TekuMetricCategory.NETWORK,
    85→            "rpc_data_column_sidecars_by_range_requested_sidecars_total",
    86→            "Total number of data column sidecars requested in accepted blob sidecars by range requests from peers");
    87→    this.dasLogger = dasLogger;
    88→  }
    89→
    90→  @Override
    91→  public Optional<RpcException> validateRequest(
    92→      final String protocolId, final DataColumnSidecarsByRangeRequestMessage request) {
    93→    final int maxRequestDataColumnSidecars = specConfigFulu.getMaxRequestDataColumnSidecars();
    94→    final int requestedCount = calculateRequestedCount(request);
    95→
    96→    if (requestedCount == -1 || requestedCount > maxRequestDataColumnSidecars) {
    97→      requestCounter.labels("count_too_big").inc();
    98→      return Optional.of(
    99→          new RpcException(
   100→              INVALID_REQUEST_CODE,
   101→              String.format(
   102→                  "Only a maximum of %s data column sidecars can be requested per request",
   103→                  maxRequestDataColumnSidecars)));
   104→    }
   105→    return Optional.empty();
   106→  }
   107→
   108→  @Override
   109→  public void onIncomingMessage(
   110→      final String protocolId,
   111→      final Eth2Peer peer,
   112→      final DataColumnSidecarsByRangeRequestMessage message,
   113→      final ResponseCallback<DataColumnSidecar> responseCallback) {
   114→    final UInt64 startSlot = message.getStartSlot();
   115→    final UInt64 endSlot = message.getMaxSlot();
   116→    final List<UInt64> columns = message.getColumns();
   117→
   118→    final ReqRespResponseLogger<DataColumnSidecar> responseLogger =
   119→        dasLogger
   120→            .getDataColumnSidecarsByRangeLogger()
   121→            .onInboundRequest(
   122→                LoggingPeerId.fromPeerAndNodeId(
   123→                    peer.getId().toBase58(), peer.getDiscoveryNodeId().orElseThrow()),
   124→                new DasReqRespLogger.ByRangeRequest(
   125→                    message.getStartSlot(), message.getCount().intValue(), message.getColumns()));
   126→    final LoggingResponseCallback<DataColumnSidecar> responseCallbackWithLogging =
   127→        new LoggingResponseCallback<>(responseCallback, responseLogger);
   128→
   129→    final int requestedCount = calculateRequestedCount(message);
   130→
   131→    final Optional<RequestKey> maybeRequestKey =
   132→        peer.approveDataColumnSidecarsRequest(responseCallbackWithLogging, requestedCount);
   133→
   134→    if (!peer.approveRequest() || maybeRequestKey.isEmpty()) {
   135→      requestCounter.labels("rate_limited").inc();
   136→      return;
   137→    }
   138→
   139→    requestCounter.labels("ok").inc();
   140→    totalDataColumnSidecarsRequestedCounter.inc(message.getCount().longValue());
   141→
   142→    UInt64 finalizedSlot = combinedChainDataClient.getFinalizedBlockSlot().orElse(UInt64.ZERO);
   143→
   144→    final SortedMap<UInt64, Bytes32> canonicalHotRoots;
   145→    if (endSlot.isGreaterThan(finalizedSlot)) {
   146→      canonicalHotRoots =
   147→          combinedChainDataClient.getAncestorRoots(startSlot, UInt64.ONE, message.getCount());
   148→
   149→      // refresh finalized slot to avoid race condition that can occur if we finalize just
   150→      // before getting hot canonical roots
   151→      finalizedSlot = combinedChainDataClient.getFinalizedBlockSlot().orElse(UInt64.ZERO);
   152→    } else {
   153→      canonicalHotRoots = ImmutableSortedMap.of();
   154→    }
   155→
   156→    final RequestState initialState =
   157→        new RequestState(
   158→            responseCallbackWithLogging,
   159→            specConfigFulu.getMaxRequestDataColumnSidecars(),
   160→            startSlot,
   161→            endSlot,
   162→            columns,
   163→            canonicalHotRoots,
   164→            finalizedSlot);
   165→
   166→    final SafeFuture<RequestState> response;
   167→    if (requestedCount == 0 || initialState.isComplete()) {
   168→      response = SafeFuture.completedFuture(initialState);
   169→    } else {
   170→      response = sendDataColumnSidecars(initialState);
   171→    }
   172→
   173→    response.finish(
   174→        requestState -> {
   175→          final int sentDataColumnSidecars = requestState.sentDataColumnSidecars.get();
   176→          if (sentDataColumnSidecars != requestedCount) {
   177→            peer.adjustDataColumnSidecarsRequest(maybeRequestKey.get(), sentDataColumnSidecars);
   178→          }
   179→          responseCallbackWithLogging.completeSuccessfully();
   180→        },
   181→        error -> {
   182→          peer.adjustDataColumnSidecarsRequest(maybeRequestKey.get(), 0);
   183→          handleProcessingRequestError(error, responseCallbackWithLogging);
   184→        });
   185→  }
   186→
   187→  private int calculateRequestedCount(final DataColumnSidecarsByRangeRequestMessage message) {
   188→    try {
   189→      return message.getCount().times(message.getColumns().size()).intValue();
   190→    } catch (final ArithmeticException e) {
   191→      return -1;
   192→    }
   193→  }
   194→
   195→  private SafeFuture<RequestState> sendDataColumnSidecars(final RequestState requestState) {
   196→    return requestState
   197→        .loadNextDataColumnSidecar()
   198→        .thenCompose(
   199→            maybeDataColumnSidecar ->
   200→                maybeDataColumnSidecar
   201→                    .map(requestState::sendDataColumnSidecar)
   202→                    .orElse(SafeFuture.COMPLETE))
   203→        .thenCompose(
   204→            __ -> {
   205→              if (requestState.isComplete()) {
   206→                return SafeFuture.completedFuture(requestState);
   207→              } else {
   208→                return sendDataColumnSidecars(requestState);
   209→              }
   210→            });
   211→  }
   212→
   213→  private void handleProcessingRequestError(
   214→      final Throwable error, final ResponseCallback<DataColumnSidecar> callback) {
   215→    final Throwable rootCause = Throwables.getRootCause(error);
   216→    if (rootCause instanceof RpcException) {
   217→      LOG.trace("Rejecting data column sidecars by range request", error);
   218→      callback.completeWithErrorResponse((RpcException) rootCause);
   219→    } else {
   220→      if (rootCause instanceof StreamClosedException
   221→          || rootCause instanceof ClosedChannelException) {
   222→        LOG.trace("Stream closed while sending requested data column sidecars", error);
   223→      } else {
   224→        LOG.error("Failed to process data column sidecars request", error);
   225→      }
   226→      callback.completeWithUnexpectedError(error);
   227→    }
   228→  }
   229→
   230→  @VisibleForTesting
   231→  class RequestState {
   232→
   233→    private final AtomicInteger sentDataColumnSidecars = new AtomicInteger(0);
   234→    private final ResponseCallback<DataColumnSidecar> callback;
   235→    private final UInt64 maxRequestDataColumnSidecars;
   236→    private final UInt64 startSlot;
   237→    private final UInt64 endSlot;
   238→    private final List<UInt64> columns;
   239→    private final UInt64 finalizedSlot;
   240→    private final Map<UInt64, Bytes32> canonicalHotRoots;
   241→
   242→    // since our storage stores hot and finalized data columns sidecar on the same "table", this
   243→    // iterator can span over hot and finalized data column sidecar
   244→    private Optional<Iterator<DataColumnSlotAndIdentifier>> dataColumnSidecarKeysIterator =
   245→        Optional.empty();
   246→
   247→    RequestState(
   248→        final ResponseCallback<DataColumnSidecar> callback,
   249→        final int maxRequestDataColumnSidecars,
   250→        final UInt64 startSlot,
   251→        final UInt64 endSlot,
   252→        final List<UInt64> columns,
   253→        final Map<UInt64, Bytes32> canonicalHotRoots,
   254→        final UInt64 finalizedSlot) {
   255→      this.callback = callback;
   256→      this.maxRequestDataColumnSidecars = UInt64.valueOf(maxRequestDataColumnSidecars);
   257→      this.startSlot = startSlot;
   258→      this.endSlot = endSlot;
   259→      this.columns = columns;
   260→      this.finalizedSlot = finalizedSlot;
   261→      this.canonicalHotRoots = canonicalHotRoots;
   262→    }
   263→
   264→    SafeFuture<Void> sendDataColumnSidecar(final DataColumnSidecar dataColumnSidecar) {
   265→      return callback.respond(dataColumnSidecar).thenRun(sentDataColumnSidecars::incrementAndGet);
   266→    }
   267→
   268→    SafeFuture<Optional<DataColumnSidecar>> loadNextDataColumnSidecar() {
   269→      if (dataColumnSidecarKeysIterator.isEmpty()) {
   270→        return combinedChainDataClient
   271→            .getDataColumnIdentifiers(startSlot, endSlot, maxRequestDataColumnSidecars)
   272→            .thenCompose(
   273→                keys -> {
   274→                  dataColumnSidecarKeysIterator =
   275→                      Optional.of(
   276→                          keys.stream()
   277→                              .filter(key -> columns.contains(key.columnIndex()))
   278→                              .iterator());
   279→                  return getNextDataColumnSidecar(dataColumnSidecarKeysIterator.get());
   280→                });
   281→      } else {
   282→        return getNextDataColumnSidecar(dataColumnSidecarKeysIterator.get());
   283→      }
   284→    }
   285→
   286→    boolean isComplete() {
   287→      return endSlot.isLessThan(startSlot)
   288→          || dataColumnSidecarKeysIterator.map(iterator -> !iterator.hasNext()).orElse(false);
   289→    }
   290→
   291→    private SafeFuture<Optional<DataColumnSidecar>> getNextDataColumnSidecar(
   292→        final Iterator<DataColumnSlotAndIdentifier> dataColumnSidecarIdentifiers) {
   293→      if (dataColumnSidecarIdentifiers.hasNext()) {
   294→        final DataColumnSlotAndIdentifier columnSlotAndIdentifier =
   295→            dataColumnSidecarIdentifiers.next();
   296→        if (finalizedSlot.isGreaterThanOrEqualTo(columnSlotAndIdentifier.slot())
   297→            // not finalized, let's check if it is on canonical chain
   298→            || isCanonicalHotDataColumnSidecar(columnSlotAndIdentifier)) {
   299→          return combinedChainDataClient.getSidecar(columnSlotAndIdentifier);
   300→        }
   301→        // non-canonical, try next one
   302→        return getNextDataColumnSidecar(dataColumnSidecarIdentifiers);
   303→      }
   304→
   305→      return SafeFuture.completedFuture(Optional.empty());
   306→    }
   307→
   308→    private boolean isCanonicalHotDataColumnSidecar(
   309→        final DataColumnSlotAndIdentifier columnSlotAndIdentifier) {
   310→      return Optional.ofNullable(canonicalHotRoots.get(columnSlotAndIdentifier.slot()))
   311→          .map(blockRoot -> blockRoot.equals(columnSlotAndIdentifier.blockRoot()))
   312→          .orElse(false);
   313→    }
   314→  }
   315→}
