    60→ */
    61→public class DataColumnSidecarsByRootMessageHandler
    62→    extends PeerRequiredLocalMessageHandler<
    63→        DataColumnSidecarsByRootRequestMessage, DataColumnSidecar> {
    64→
    65→  private static final Logger LOG = LogManager.getLogger();
    66→
    67→  private final Spec spec;
    68→  private final CombinedChainDataClient combinedChainDataClient;
    69→  private final Supplier<? extends DataColumnSidecarByRootCustody> dataColumnSidecarCustodySupplier;
    70→  private final Supplier<CustodyGroupCountManager> custodyGroupCountManagerSupplier;
    71→
    72→  private final LabelledMetric<Counter> requestCounter;
    73→  private final Counter totalDataColumnSidecarsRequestedCounter;
    74→  private final DasReqRespLogger dasLogger;
    75→  private final SpecConfigFulu specConfigFulu;
    76→
    77→  public DataColumnSidecarsByRootMessageHandler(
    78→      final Spec spec,
    79→      final MetricsSystem metricsSystem,
    80→      final CombinedChainDataClient combinedChainDataClient,
    81→      final Supplier<? extends DataColumnSidecarByRootCustody> dataColumnSidecarCustodySupplier,
    82→      final Supplier<CustodyGroupCountManager> custodyGroupCountManagerSupplier,
    83→      final DasReqRespLogger dasLogger) {
    84→    this.spec = spec;
    85→    this.combinedChainDataClient = combinedChainDataClient;
    86→    this.custodyGroupCountManagerSupplier = custodyGroupCountManagerSupplier;
    87→    this.dataColumnSidecarCustodySupplier = dataColumnSidecarCustodySupplier;
    88→    this.dasLogger = dasLogger;
    89→    this.specConfigFulu =
    90→        SpecConfigFulu.required(spec.forMilestone(SpecMilestone.FULU).getConfig());
    91→    this.requestCounter =
    92→        metricsSystem.createLabelledCounter(
    93→            TekuMetricCategory.NETWORK,
    94→            "rpc_data_column_sidecars_by_root_requests_total",
    95→            "Total number of data column sidecars by root requests received",
    96→            "status");
    97→    this.totalDataColumnSidecarsRequestedCounter =
    98→        metricsSystem.createCounter(
    99→            TekuMetricCategory.NETWORK,
   100→            "rpc_data_column_sidecars_by_root_requested_data_column_sidecars_total",
   101→            "Total number of data column sidecars requested in accepted data column sidecars by root requests from peers");
   102→  }
   103→
   104→  private SafeFuture<Boolean> validateAndMaybeRespond(
   105→      final DataColumnIdentifier identifier,
   106→      final Optional<DataColumnSidecar> maybeSidecar,
   107→      final ResponseCallback<DataColumnSidecar> callback) {
   108→    return validateMinimumRequestEpoch(identifier, maybeSidecar)
   109→        .thenCompose(
   110→            __ ->
   111→                maybeSidecar
   112→                    .map(sideCar -> callback.respond(sideCar).thenApply(___ -> true))
   113→                    .orElse(SafeFuture.completedFuture(false)));
   114→  }
   115→
   116→  @Override
   117→  public Optional<RpcException> validateRequest(
   118→      final String protocolId, final DataColumnSidecarsByRootRequestMessage request) {
   119→    final int maxRequestIdentifiers = specConfigFulu.getMaxRequestBlocksDeneb();
   120→    if (request.size() > maxRequestIdentifiers) {
   121→      requestCounter.labels("count_too_big").inc();
   122→      return Optional.of(
   123→          new RpcException(
   124→              INVALID_REQUEST_CODE,
   125→              String.format(
   126→                  "Only a maximum of %d by root identifiers are allowed per request",
   127→                  maxRequestIdentifiers)));
   128→    }
   129→    return Optional.empty();
   130→  }
   131→
   132→  @Override
   133→  public void onIncomingMessage(
   134→      final String protocolId,
   135→      final Eth2Peer peer,
   136→      final DataColumnSidecarsByRootRequestMessage message,
   137→      final ResponseCallback<DataColumnSidecar> responseCallback) {
   138→    final int requestedDataColumnSidecarsCount = message.getMaximumResponseChunks();
   139→
   140→    final ReqRespResponseLogger<DataColumnSidecar> responseLogger =
   141→        dasLogger
   142→            .getDataColumnSidecarsByRootLogger()
   143→            .onInboundRequest(
   144→                LoggingPeerId.fromPeerAndNodeId(
   145→                    peer.getId().toBase58(), peer.getDiscoveryNodeId().orElseThrow()),
   146→                message.asList());
   147→
   148→    final LoggingResponseCallback<DataColumnSidecar> responseCallbackWithLogging =
   149→        new LoggingResponseCallback<>(responseCallback, responseLogger);
   150→
   151→    final Optional<RequestKey> maybeRequestKey =
   152→        peer.approveDataColumnSidecarsRequest(
   153→            responseCallbackWithLogging, requestedDataColumnSidecarsCount);
   154→
   155→    if (!peer.approveRequest() || maybeRequestKey.isEmpty()) {
   156→      requestCounter.labels("rate_limited").inc();
   157→      return;
   158→    }
   159→
   160→    requestCounter.labels("ok").inc();
   161→    totalDataColumnSidecarsRequestedCounter.inc(requestedDataColumnSidecarsCount);
   162→
   163→    final Set<UInt64> myCustodyColumns =
   164→        new HashSet<>(custodyGroupCountManagerSupplier.get().getCustodyColumnIndices());
   165→    final Stream<SafeFuture<Boolean>> responseStream =
   166→        message.stream()
   167→            .flatMap(
   168→                byRootIdentifier ->
   169→                    byRootIdentifier.getColumns().stream()
   170→                        .filter(myCustodyColumns::contains)
   171→                        .map(
   172→                            column ->
   173→                                new DataColumnIdentifier(byRootIdentifier.getBlockRoot(), column)))
   174→            .map(
   175→                dataColumnIdentifier ->
   176→                    retrieveDataColumnSidecar(dataColumnIdentifier)
   177→                        .thenCompose(
   178→                            maybeSidecar ->
   179→                                validateAndMaybeRespond(
   180→                                    dataColumnIdentifier,
   181→                                    maybeSidecar,
   182→                                    responseCallbackWithLogging)));
   183→
   184→    final SafeFuture<List<Boolean>> listOfResponses = SafeFuture.collectAll(responseStream);
   185→
   186→    listOfResponses
   187→        .thenApply(list -> list.stream().filter(isSent -> isSent).count())
   188→        .thenAccept(
   189→            sentDataColumnSidecarsCount -> {
   190→              if (sentDataColumnSidecarsCount != requestedDataColumnSidecarsCount) {
   191→                peer.adjustDataColumnSidecarsRequest(
   192→                    maybeRequestKey.get(), sentDataColumnSidecarsCount);
   193→              }
   194→              responseCallbackWithLogging.completeSuccessfully();
   195→            })
   196→        .finish(
   197→            err -> {
   198→              peer.adjustDataColumnSidecarsRequest(maybeRequestKey.get(), 0);
   199→              handleError(responseCallbackWithLogging, err);
   200→            });
   201→  }
   202→
   203→  private SafeFuture<Optional<DataColumnSidecar>> getNonCanonicalDataColumnSidecar(
   204→      final DataColumnIdentifier identifier) {
   205→    return combinedChainDataClient
   206→        .getBlockByBlockRoot(identifier.blockRoot())
   207→        .thenApply(maybeBlock -> maybeBlock.map(SignedBeaconBlock::getSlot))
   208→        .thenCompose(
   209→            maybeSlot -> {
   210→              if (maybeSlot.isPresent()) {
   211→                return combinedChainDataClient.getNonCanonicalSidecar(
   212→                    new DataColumnSlotAndIdentifier(
   213→                        maybeSlot.get(), identifier.blockRoot(), identifier.columnIndex()));
   214→              } else {
   215→                return SafeFuture.completedFuture(Optional.empty());
   216→              }
   217→            });
   218→  }
   219→
   220→  /**
   221→   * Validations:
   222→   *
   223→   * <ul>
   224→   *   <li>The block root references a block greater than or equal to the minimum_request_epoch
   225→   * </ul>
   226→   */
   227→  @SuppressWarnings("unused")
   228→  private SafeFuture<Void> validateMinimumRequestEpoch(
   229→      final DataColumnIdentifier identifier, final Optional<DataColumnSidecar> maybeSidecar) {
   230→    return maybeSidecar
   231→        .map(sidecar -> SafeFuture.completedFuture(Optional.of(sidecar.getSlot())))
   232→        .orElseGet(
   233→            () ->
   234→                combinedChainDataClient
   235→                    .getBlockByBlockRoot(identifier.blockRoot())
   236→                    .exceptionally(ThrottlingStorageQueryChannel::ignoreQueueIsFullException)
   237→                    .thenApply(maybeBlock -> maybeBlock.map(SignedBeaconBlock::getSlot)))
   238→        .thenAcceptChecked(
   239→            maybeSlot -> {
   240→              if (maybeSlot.isEmpty()) {
   241→                return;
   242→              }
   243→              final UInt64 requestedEpoch = spec.computeEpochAtSlot(maybeSlot.get());
   244→              if (!spec.isAvailabilityOfDataColumnSidecarsRequiredAtEpoch(
   245→                  combinedChainDataClient.getStore(), requestedEpoch)) {
   246→                throw new RpcException(
   247→                    INVALID_REQUEST_CODE,
   248→                    String.format(
   249→                        "Block root (%s) references a block earlier than the minimum_request_epoch",
   250→                        identifier.blockRoot()));
   251→              }
   252→            });
   253→  }
   254→
   255→  private SafeFuture<Optional<DataColumnSidecar>> retrieveDataColumnSidecar(
   256→      final DataColumnIdentifier identifier) {
   257→    return dataColumnSidecarCustodySupplier
   258→        .get()
   259→        .getCustodyDataColumnSidecarByRoot(identifier)
   260→        .thenCompose(
   261→            maybeSidecar -> {
   262→              if (maybeSidecar.isPresent()) {
   263→                return SafeFuture.completedFuture(maybeSidecar);
   264→              }
   265→              // Fallback to non-canonical sidecar if the canonical one is not found
   266→              return getNonCanonicalDataColumnSidecar(identifier);
   267→            })
   268→        .exceptionally(ThrottlingStorageQueryChannel::ignoreQueueIsFullException);
   269→  }
   270→
   271→  private void handleError(
   272→      final ResponseCallback<DataColumnSidecar> callback, final Throwable error) {
   273→    final Throwable rootCause = Throwables.getRootCause(error);
   274→    if (rootCause instanceof RpcException) {
   275→      LOG.trace("Rejecting data column sidecars by root request", error);
   276→      callback.completeWithErrorResponse((RpcException) rootCause);
   277→    } else {
   278→      if (rootCause instanceof StreamClosedException
   279→          || rootCause instanceof ClosedChannelException) {
   280→        LOG.trace("Stream closed while sending requested data column sidecars", error);
   281→      } else {
   282→        LOG.error("Failed to process data column sidecars by root request", error);
   283→      }
   284→      callback.completeWithUnexpectedError(error);
   285→    }
   286→  }
   287→}
