   123→  private Spec(
   124→      final SpecConfigAndParent<? extends SpecConfig> specConfigAndParent,
   125→      final Map<SpecMilestone, SpecVersion> specVersions,
   126→      final ForkSchedule forkSchedule) {
   127→    Preconditions.checkArgument(specVersions != null && !specVersions.isEmpty());
   128→    Preconditions.checkArgument(forkSchedule != null);
   129→    this.specConfigAndParent = specConfigAndParent;
   130→    this.specVersions = specVersions;
   131→    this.forkSchedule = forkSchedule;
   132→
   133→    // Setup state transition
   134→    this.stateTransition = new StateTransition(this::atSlot);
   135→  }
