   137→  static Spec create(
   138→      final SpecConfigAndParent<? extends SpecConfig> specConfigAndParent,
   139→      final SpecMilestone highestMilestoneSupported) {
   140→    final Map<SpecMilestone, SpecVersion> specVersions = new EnumMap<>(SpecMilestone.class);
   141→    final ForkSchedule.Builder forkScheduleBuilder = ForkSchedule.builder();
   142→    final SchemaRegistryBuilder schemaRegistryBuilder = SchemaRegistryBuilder.create();
   143→
   144→    for (SpecMilestone milestone : SpecMilestone.getMilestonesUpTo(highestMilestoneSupported)) {
   145→      SpecVersion.create(
   146→              milestone, specConfigAndParent.forMilestone(milestone), schemaRegistryBuilder)
   147→          .ifPresent(
   148→              milestoneSpec -> {
   149→                forkScheduleBuilder.addNextMilestone(milestoneSpec);
   150→                specVersions.put(milestone, milestoneSpec);
   151→              });
   152→    }
   153→
   154→    final ForkSchedule forkSchedule = forkScheduleBuilder.build();
   155→
   156→    return new Spec(specConfigAndParent, specVersions, forkSchedule);
   157→  }
