   631→  public int computeSubnetForAttestation(final BeaconState state, final Attestation attestation) {
   632→    final UInt64 stateEpoch = getCurrentEpoch(state);
   633→    final UInt64 attestationEpoch =
   634→        atEpoch(stateEpoch).miscHelpers().computeEpochAtSlot(attestation.getData().getSlot());
   635→    final UInt64 earliestEpochInRange =
   636→        attestationEpoch.minusMinZero(atEpoch(attestationEpoch).getConfig().getMaxSeedLookahead());
   637→    if (stateEpoch.isLessThan(earliestEpochInRange)) {
   638→      final UInt64 earliestSlot =
   639→          atEpoch(stateEpoch).miscHelpers().computeStartSlotAtEpoch(earliestEpochInRange);
   640→      LOG.debug(
   641→          "Processing empty slots for state at slot {}, target slot {}",
   642→          state.getSlot(),
   643→          earliestSlot);
   644→      try {
   645→        final BeaconState advancedState = processSlots(state, earliestSlot);
   646→        return atState(advancedState)
   647→            .getBeaconStateUtil()
   648→            .computeSubnetForAttestation(advancedState, attestation);
   649→      } catch (SlotProcessingException | EpochProcessingException e) {
   650→        LOG.debug("Couldn't wind state at slot {} forward", state.getSlot(), e);
   651→      }
   652→    }
   653→
   654→    return atState(state).getBeaconStateUtil().computeSubnetForAttestation(state, attestation);
   655→  }
