  1047→  /**
  1048→   * This method is used to setup caches and limits during the initialization of the node. We
  1049→   * normally increase the blobs with each fork, but in case we will decrease them, let's consider
  1050→   * the last two forks.
  1051→   */
  1052→  public Optional<Integer> getMaxBlobsPerBlockForHighestMilestone() {
  1053→    final SpecMilestone highestSupportedMilestone =
  1054→        getForkSchedule().getHighestSupportedMilestone();
  1055→
  1056→    // query the blob_schedule after FULU
  1057→    if (highestSupportedMilestone.isGreaterThanOrEqualTo(FULU)) {
  1058→      final Optional<Integer> maybeHighestMaxBlobsPerBlockFromBpoForkSchedule =
  1059→          forMilestone(FULU)
  1060→              .miscHelpers()
  1061→              .toVersionFulu()
  1062→              .flatMap(MiscHelpersFulu::getHighestMaxBlobsPerBlockFromBpoForkSchedule);
  1063→      // only use BPO fork max_blobs_per_block if it is present
  1064→      if (maybeHighestMaxBlobsPerBlockFromBpoForkSchedule.isPresent()) {
  1065→        return maybeHighestMaxBlobsPerBlockFromBpoForkSchedule;
  1066→      }
  1067→    }
  1068→
  1069→    final Optional<Integer> maybeHighestMaxBlobsPerBlock =
  1070→        forMilestone(highestSupportedMilestone)
  1071→            .getConfig()
  1072→            .toVersionDeneb()
  1073→            .map(SpecConfigDeneb::getMaxBlobsPerBlock);
  1074→
  1075→    final Optional<Integer> maybeSecondHighestMaxBlobsPerBlock =
  1076→        highestSupportedMilestone
  1077→            .getPreviousMilestoneIfExists()
  1078→            .map(this::forMilestone)
  1079→            .map(SpecVersion::getConfig)
  1080→            .flatMap(SpecConfig::toVersionDeneb)
  1081→            .map(SpecConfigDeneb::getMaxBlobsPerBlock);
  1082→
  1083→    if (maybeHighestMaxBlobsPerBlock.isEmpty() && maybeSecondHighestMaxBlobsPerBlock.isEmpty()) {
  1084→      return Optional.empty();
  1085→    }
  1086→
  1087→    final int highestMaxBlobsPerBlock = maybeHighestMaxBlobsPerBlock.orElse(0);
  1088→    final int secondHighestMaxBlobsPerBlock = maybeSecondHighestMaxBlobsPerBlock.orElse(0);
  1089→    final int max = Math.max(highestMaxBlobsPerBlock, secondHighestMaxBlobsPerBlock);
  1090→
  1091→    return Optional.of(max);
  1092→  }
