  1168→  }
  1169→
  1170→  private Fork getForkAtSlot(final UInt64 slot) {
  1171→    return forkSchedule.getFork(computeEpochAtSlot(slot));
  1172→  }
  1173→
  1174→  private UInt64 getProposerSlashingEpoch(final ProposerSlashing proposerSlashing) {
  1175→    // Slashable blocks must be from same slot
  1176→    return computeEpochAtSlot(proposerSlashing.getHeader1().getMessage().getSlot());
  1177→  }
