  1179→  @Override
  1180→  public boolean equals(final Object o) {
  1181→    if (this == o) {
  1182→      return true;
  1183→    }
  1184→    if (o == null || getClass() != o.getClass()) {
  1185→      return false;
  1186→    }
  1187→    final Spec spec = (Spec) o;
  1188→    return Objects.equals(forkSchedule, spec.forkSchedule);
  1189→  }
