  1195→
  1196→  public Optional<Integer> getMaxBlobsPerBlockAtSlot(final UInt64 slot) {
  1197→    final SpecVersion specVersion = atSlot(slot);
  1198→    return switch (specVersion.getMilestone()) {
  1199→      case PHASE0, ALTAIR, BELLATRIX, CAPELLA -> Optional.empty();
  1200→      case DENEB, ELECTRA ->
  1201→          Optional.of(SpecConfigDeneb.required(specVersion.getConfig()).getMaxBlobsPerBlock());
  1202→      case FULU, GLOAS -> {
  1203→        final UInt64 epoch = specVersion.miscHelpers().computeEpochAtSlot(slot);
  1204→        yield Optional.of(
  1205→            MiscHelpersFulu.required(specVersion.miscHelpers())
  1206→                .getBlobParameters(epoch)
  1207→                .maxBlobsPerBlock());
  1208→      }
  1209→    };
  1210→  }
