    77→  @Override
    78→  public void validateExecutionPayload(
    79→      final BeaconState genericState,
    80→      final BeaconBlockBody beaconBlockBody,
    81→      final Optional<? extends OptimisticExecutionPayloadExecutor> payloadExecutor)
    82→      throws BlockProcessingException {
    83→    final int maxBlobsPerBlock = getMaxBlobsPerBlock(genericState);
    84→    final SszList<SszKZGCommitment> blobKzgCommitments = extractBlobKzgCommitments(beaconBlockBody);
