    98→    final List<VersionedHash> versionedHashes =
    99→        blobKzgCommitments.stream()
   100→            .map(SszKZGCommitment::getKZGCommitment)
   101→            .map(miscHelpers::kzgCommitmentToVersionedHash)
   102→            .toList();
   103→    final Bytes32 parentBeaconBlockRoot = state.getLatestBlockHeader().getParentRoot();
   104→    return new NewPayloadRequest(executionPayload, versionedHashes, parentBeaconBlockRoot);
   105→  }
